    'admin_shadow-saas-grip.abort_failed_prefix' => 'Interruzione della sincronizzazione non riuscita: ',
    'admin_shadow-saas-grip.abort_grip_confirm' => 'Interrompere la sincronizzazione Grip in corso?',
    'admin_shadow-saas-grip.abort_hero_confirm' => 'Interrompere la sincronizzazione HERO in corso?',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security individua e monitora continuamente le applicazioni SaaS-of-Record nel tuo ambiente.
Questa integrazione:<br><br>
<strong>&bull; Replica i dati Grip:</strong> Preleva l\'intero inventario SaaS / utenti / avvisi nelle tabelle <code>shadow_saas_grip_*</code>.<br>
<strong>&bull; Idrata Shadow SaaS:</strong> Proietta ogni app SaaS nell\'elenco Shadow SaaS esistente, normalizzando l\'URL al suo dominio registrabile in modo che l\'abbinamento dei fornitori funzioni come per un\'importazione CSV.<br>
<strong>&bull; Traccia il rischio:</strong> Conserva il punteggio di rischio Grip, il tag di sanzione, i conteggi degli ambiti OAuth, la classificazione della profondita AI, il supporto MFA / SAML e i metadati del contatto principale.<br>
<strong>&bull; Resta aggiornato:</strong> Viene rieseguito secondo la pianificazione cron configurata; gli amministratori possono anche attivare un\'esecuzione immediata in background con il pulsante "Esegui ora" qui sopra.',
    'admin_shadow-saas-grip.about_grip_heading' => 'Informazioni sull\'integrazione Grip',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security individua i fornitori SaaS di terze parti e i problemi che li interessano nel tuo ambiente.
Questa integrazione:<br><br>
<strong>&bull; Replica i dati HERO:</strong> Preleva fornitori / problemi / utenti per-fornitore nelle tabelle <code>shadow_saas_hero_*</code>.<br>
<strong>&bull; Idrata Shadow SaaS:</strong> Proietta ogni fornitore nell\'elenco Shadow SaaS esistente tramite dominio registrabile, in modo che l\'abbinamento funzioni come per un\'importazione CSV.<br>
<strong>&bull; Traccia il rischio:</strong> Deriva un punteggio di rischio 1-5 dal peggior problema aperto per fornitore (la stessa scala 1-5 usata da Grip) e registra lo stato del fornitore e gli aspetti di coinvolgimento.<br>
<strong>&bull; Resta aggiornato:</strong> Viene rieseguito nel job condiviso di Re-idratazione pianificata; gli amministratori possono anche attivare un\'esecuzione immediata con il pulsante "Esegui ora" qui sotto.',
    'admin_shadow-saas-grip.about_hero_heading' => 'Informazioni sull\'integrazione HERO',
    'admin_shadow-saas-grip.api_key_label' => 'Chiave API',
    'admin_shadow-saas-grip.api_reference_heading' => 'Riferimento API',
    'admin_shadow-saas-grip.api_token_help' => 'Inviato come intestazione HTTP <code>access-token</code> a ogni richiesta. Lasciare vuoto per mantenere il token esistente.',
    'admin_shadow-saas-grip.api_token_label' => 'Token API',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => 'L\'host dell\'URL API non e consentito.',
    'admin_shadow-saas-grip.api_url_invalid' => 'L\'URL API deve essere un URL http(s) valido.',
    'admin_shadow-saas-grip.api_url_label' => 'URL API',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' app con utenti',
    'admin_shadow-saas-grip.client_id_label' => 'Client ID',
    'admin_shadow-saas-grip.client_secret_label' => 'Client Secret',
    'admin_shadow-saas-grip.currently_holding_prefix' => 'Attualmente contiene ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>Live</strong> richiama l\'API Grip per ogni pagina (sempre aggiornato, piu oneroso per l\'API). <strong>Locale (idratato/in cache)</strong> serve le tabelle idratate <code>shadow_saas_grip_*</code> nel database - piu leggero per l\'API - e uno snapshot per-app mancante viene recuperato dall\'API una sola volta, poi messo in cache. In modalita Locale, ogni sincronizzazione <strong>aggiorna completamente</strong> i dati: le tabelle mirror Grip vengono svuotate e re-idratate dall\'API.',
    'admin_shadow-saas-grip.data_source_label' => 'Origine dati',
    'admin_shadow-saas-grip.data_source_live' => 'Live - interroga l\'API Grip a ogni visualizzazione',
    'admin_shadow-saas-grip.data_source_local' => 'Locale (idratato/in cache) - servito dal database',
    'admin_shadow-saas-grip.download_postman_json' => 'Scarica Postman (JSON)',
    'admin_shadow-saas-grip.download_swagger_yaml' => 'Scarica Swagger (YAML)',
    'admin_shadow-saas-grip.enable_grip' => 'Abilita l\'integrazione Grip Security',
    'admin_shadow-saas-grip.enable_hero' => 'Abilita l\'integrazione HERO Security',
    'admin_shadow-saas-grip.enable_scheduled_rehydration' => 'Abilita re-idratazione pianificata',
    'admin_shadow-saas-grip.enable_zscaler' => 'Abilita il blocco Zscaler per Categoria URL su Nega',
    'admin_shadow-saas-grip.enter_admin_api_key' => 'Inserisci la chiave API dell\'amministratore',
    'admin_shadow-saas-grip.failed_truncate_prefix' => 'Impossibile svuotare ',
    'admin_shadow-saas-grip.flow_grip_breach_label' => 'Trasferisci le informazioni sulle violazioni Grip in Violazioni&nbsp;/&nbsp;Avvisi Cyber',
    'admin_shadow-saas-grip.grip_all_cleared_p1' => 'Tutti i dati Grip cancellati: ',
    'admin_shadow-saas-grip.grip_all_cleared_p2' => ' tabella/e mirror svuotata/e, ',
    'admin_shadow-saas-grip.grip_all_cleared_p3' => ' riga/righe Shadow SaaS rimossa/e e ',
    'admin_shadow-saas-grip.grip_all_cleared_p4' => ' record fornitore ripuliti dalla telemetria Grip registrata.',
    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Inventario degli endpoint per l\'API pubblica Grip Security (server base <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, OpenAPI 3.1 auto-generato). La sincronizzazione FairTPRM consuma gli endpoint di lettura (GET) contrassegnati come <em>usato dalla sincronizzazione</em>; l\'inventario completo &mdash; inclusi i gruppi Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions e AI&nbsp;Agents &mdash; e disponibile nei download OpenAPI e Postman qui sotto. L\'estrazione del dominio normalizza gli URL al loro dominio registrabile (ad es. <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>).',
    'admin_shadow-saas-grip.grip_auth_help' => 'Intestazione di autenticazione: <code>access-token: &lt;your-token&gt;</code>. La variabile <code>accessToken</code> della collezione Postman e impostata su <code>REPLACE_ME</code>; sostituisci il token del tuo tenant prima di inviare le richieste.',
    'admin_shadow-saas-grip.grip_base_url_help' => 'URL Grip con prefisso tenant radicato in <code>/public/saas</code> (ad es. <code>https://tenant.dep.grip.security/public/saas</code>). Gli endpoint correlati (<code>/public/users</code>, <code>/public/alerts</code>) sono derivati da questo host.',
    'admin_shadow-saas-grip.grip_base_url_label' => 'Server (URL base del tenant)',
    'admin_shadow-saas-grip.grip_breach_help' => 'A ogni re-idratazione pianificata (e con l\'<strong>Esegui&nbsp;ora</strong> manuale qui sotto), gli avvisi Grip "Security Incident Detected" vengono scritti nel sistema <a href="breach-alerts.php">Violazioni&nbsp;/&nbsp;Avvisi Cyber</a> (deduplicati). Le violazioni relative a un fornitore gia onboardato sono collegate a quel fornitore; le violazioni relative a un\'app senza un fornitore onboardato vengono comunque registrate e contrassegnate come <strong>Shadow&nbsp;SaaS</strong> con il numero di utenti potenzialmente interessati. Richiede Grip abilitato (sopra) <em>e</em> l\'impostazione Violazione&nbsp;/&nbsp;Avviso Cyber in <a href="admin.php?section=email">Email &amp; Avvisi</a>.',
    'admin_shadow-saas-grip.grip_config_update_failed_prefix' => 'Aggiornamento della configurazione Grip non riuscito: ',
