    'admin_shadow-saas-grip.truncate_all_confirm' => 'Svuotare TUTTI i dati Grip locali? Questa operazione elimina definitivamente ogni riga mirror Grip (app, utenti, avvisi, utenti per-app), rimuove tutte le righe Shadow SaaS proiettate da Grip e cancella la telemetria Grip curata registrata sui record fornitore (la scheda \'SaaS Data\' del fornitore). La sincronizzazione successiva la re-idrata dall\'API Grip. Questa operazione non puo essere annullata.',
