    'admin_shadow-saas-grip.zscaler_intro' => 'Quando un fornitore viene negato dall\'elenco Shadow SaaS, il dominio del fornitore viene aggiunto alla Categoria URL qui sotto in Zscaler ZIA (usando <code>action=ADD_TO_LIST</code>) e poi attivato. Condiviso da entrambi i provider.',
