    'admin_shadow-saas-grip.zscaler_vanity_label' => 'Dominio Vanity ZIdentity',
    'admin_shodan-srs.about_body' => 'Shodan e una piattaforma di intelligence di internet che scansiona e indicizza ogni dispositivo connesso a internet che riesce a trovare. L\'integrazione consente:<br><br><strong>• Scansione delle porte:</strong> Identifica le porte aperte nell\'infrastruttura del fornitore, inclusi i servizi ad alto rischio (FTP, Telnet, RDP, SMB)<br><strong>• Rilevamento delle vulnerabilita:</strong> Individua le CVE note associate agli indirizzi IP e ai servizi del fornitore<br><strong>• Identificazione dei servizi:</strong> Cataloga i servizi in esecuzione, le versioni del software e le configurazioni dei server<br><strong>• Punteggio di sicurezza:</strong> Genera un punteggio di sicurezza da 0 a 100 basato sulla superficie di attacco esposta',
    'admin_shodan-srs.about_heading' => 'Informazioni su Shodan',
    'admin_shodan-srs.about_learn_more' => 'Scopri di piu su Shodan →',
    'admin_shodan-srs.about_note_body' => 'I punteggi Shodan sono complementari ai punteggi UpGuard. UpGuard si concentra sulla postura di sicurezza complessiva (scala 0-950), mentre Shodan si concentra sull\'infrastruttura esposta (scala 0-100). Entrambi possono essere abilitati contemporaneamente per valutazioni complete dei fornitori.',
    'admin_shodan-srs.about_note_label' => 'Nota:',
    'admin_shodan-srs.across' => 'per',
    'admin_shodan-srs.active_waiver_singular' => 'deroga attiva',
    'admin_shodan-srs.active_waivers_plural' => 'deroghe attive',
    'admin_shodan-srs.api_key_help' => 'Chiave API dal tuo <a href="https://account.shodan.io" target="_blank">account Shodan</a>. Lasciare vuoto per mantenere la chiave esistente.',
    'admin_shodan-srs.api_key_label' => 'Chiave API Shodan',
