    'admin_shodan-srs.banner_max_age_help' => 'Ignora i dati dei banner di Shodan piu vecchi di questo numero di giorni. Shodan conserva i dati storici delle porte che potrebbero ora essere filtrate/chiuse. Impostare a 0 per disabilitare il filtro di aggiornamento. Predefinito: 7 giorni.',
