    'admin_shodan-srs.min_cve_year_help_prefix' => 'Escludi dai risultati della scansione le CVE pubblicate prima di questo anno. Predefinito: 0 = automatico (anno corrente meno 5, attualmente ',
    'admin_shodan-srs.min_cve_year_help_suffix' => '). Il rilevamento basato sui banner di Shodan spesso associa CVE molto vecchie alle stringhe di versione del software, generando falsi positivi. Impostare un anno specifico per sovrascrivere, oppure lasciare 0 per utilizzare la finestra mobile di 5 anni.',
