    'admin_shodan-srs.on_demand_help' => 'Se abilitato, Shodan richiedera una scansione su richiesta per qualsiasi IP per cui non dispone di dati esistenti durante il calcolo del punteggio. Questo garantisce la copertura dei domini che Shodan non ha scansionato in precedenza, ma consuma crediti di scansione (1 credito per IP) e aggiunge fino a 3 minuti di attesa per ogni richiesta di calcolo del punteggio mentre Shodan elabora la scansione. Consigliato per i fornitori per i quali Shodan non restituisce segnali di sicurezza.',
