    'admin_shodan-srs.word_waiver' => 'deroga',
    'admin_shodan-srs.word_waivers' => 'deroghe',
    'admin_srs.about_custom_body' => 'Il punteggio personalizzato ti consente di inserire manualmente i punteggi di sicurezza per i fornitori utilizzando strumenti di valutazione o servizi di rating esterni.<br><br><strong>Intervallo del punteggio:</strong> 1-100 (scala percentuale)<br><strong>Valutazione:</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>Quando esistono più fonti di punteggio (UpGuard, Shodan, Personalizzato), viene calcolato e visualizzato in tutta l\'applicazione un punteggio medio combinato. Questo fornisce una visione unificata della postura di sicurezza di ciascun fornitore da tutte le fonti disponibili.',
    'admin_srs.about_custom_heading' => 'Informazioni sul punteggio personalizzato',
    'admin_srs.about_upguard_body' => 'UpGuard CyberRisk fornisce valutazioni di sicurezza automatizzate e monitoraggio continuo per i fornitori terzi. L\'integrazione consente:<br><br><strong>• Punteggio di sicurezza automatizzato:</strong> ottieni valutazioni di sicurezza immediate (0-950) per i fornitori in base alla loro postura di sicurezza esterna<br><strong>• Identificazione dei rischi:</strong> identifica automaticamente i rischi di sicurezza di gravità alta, media e bassa<br><strong>• Analisi delle tendenze:</strong> monitora nel tempo i punteggi di sicurezza dei fornitori per individuare miglioramenti o peggioramenti<br><strong>• Monitoraggio per livello:</strong> configura la frequenza di ricalcolo in base alla criticità del fornitore',
    'admin_srs.about_upguard_heading' => 'Informazioni su UpGuard CyberRisk',
    'admin_srs.about_upguard_learn_more' => 'Scopri di più su UpGuard CyberRisk &rarr;',
