    'admin_srs.cron_lock_files_note' => 'Usa file di lock per evitare esecuzioni sovrapposte. Consulta la <span data-action="openCronInfoModal" style="color: var(--theme-header-color, #2563eb); cursor: pointer; text-decoration: underline;">Guida alla configurazione di Cron</span> per i dettagli.',
    'admin_srs.cron_modal_heading' => 'Configurazione del processo Cron per il ricalcolo SRS',
    'admin_srs.cron_note_body' => 'La cronologia delle esecuzioni è registrata nel database. Controlla Amministrazione &gt; SRS per le esecuzioni passate ed eventuali errori.',
    'admin_srs.cron_ondemand_desc' => 'Elabora le richieste di ricalcolo manuale accodate dalla pagina dei dettagli del fornitore. <strong>Richiesta</strong> quando "Usa Cron per il ricalcolo" è abilitato su una delle integrazioni:',
