    'admin_srs.cron_ondemand_note' => 'Viene eseguita ogni minuto. Usa file di lock per evitare esecuzioni sovrapposte. Elabora un solo fornitore alla volta per evitare i limiti di frequenza dell\'API. Se non esistono ricalcoli in sospeso, il processo termina immediatamente.',
